starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

starter.variables.tf:
variable "volume_name" {
  description = "Input variable volume_name."
  type        = string
  default     = "app-data"
}

starter.main.tf:
provider "docker" {
  host = var.docker_host
}

